def V(w, pt, s): return [w, pt, 'Soa como “%s”.' % s]
def Q(q, pt, opts, a, line, why): return dict(q=q, pt=pt, opts=[list(o) for o in opts], a=a, line=line, why=why)
def H(e, x, y, en, pt, say, sayPt): return dict(e=e, x=x, y=y, en=en, pt=pt, say=say, sayPt=sayPt)
def G(q, pt, opts, a, why): return dict(q=q, pt=pt, opts=opts, a=a, why=why)
def T(opts, a, why, q='Qual frase está certa?'): return dict(q=q, opts=opts, a=a, why=why)
def EXP(ic, en, tag, pt, use, ex_en, ex_pt): return dict(ic=ic, en=en, tag=tag, pt=pt, use=use, ex=[ex_en, ex_pt])
def VBI(v, ic, pt, i_s, he_s, ex_en, ex_pt, note):
    return dict(v=v, ic=ic, pt=pt, f=[['eu', i_s], ['ele/ela', he_s]], ex=[ex_en, ex_pt], note=note)
def RND(say, opts, a, why): return dict(fig='🎧', say=say, ask='Qual palavra você ouviu?', opts=opts, a=a, why=why)
def HW(say, opts, a, why): return dict(fig='🎧', say=say, ask='Ouça e toque na palavra.', opts=opts, a=a, why=why)
def HP(say, emos, a, why): return dict(fig='🎧', say=say, ask='Ouça e toque na figura.', opts=[[e, ''] for e in emos], a=a, why=why, pic=1)
def MOLD(label, slots, end='.'):
    return dict(label=label, slots=[dict(cat=c, opts=[list(o) for o in os_]) for c, os_ in slots], end=[end, end])
def MG(text, pt, opts, a, why, say): return dict(text=text, pt=pt, opts=opts, a=a, why=why, say=say)
def MT(ask, opts, a, why, say=None):
    d = dict(ask=ask, opts=opts, a=a, why=why)
    if say: d['say'] = say
    return d
def XQ(ask, opts, a, why): return dict(ask=ask, opts=opts, a=a, why=why)
def CXI(text, pt, right, d1, d2): return dict(text=text, pt=pt, opts=[right, d1, d2], a=0)
def tp(*groups): return [[list(p) for p in g] for g in groups]
def MS(ic, name, desc, prompt, ph, chips, model, check, kw, tips, ok, reply):
    return dict(ic=ic, name=name, desc=desc, data=dict(prompt=prompt, ph=ph, chips=chips, model=model, check=check, kw=kw, tips=tp(*tips), ok=ok, reply=reply))
def rsd(lst):
    keys = 'review dquiz rdg pat vplay build order soundlab produce wrap dictate'.split()
    assert len(lst) == 11
    return dict(zip(keys, lst))


def ep(n, title, sub, label, why, vocab, balloons, cover, cover_sub, cover_say, recap, teaser, cast, lines, quiz, rdg, dictate,
       produce, rs, sc, names, stage, obra, gancho, hot, gap, trap, sticker, rule, mission_ic, exp, exp_scene, lab, hunt, verbs, MR, CX):
    pr = dict(produce); pr['tips'] = tp(*pr['tips'])
    B = dict(title=title, sub=sub, pattern_label=label, why=why, vocab=vocab, balloons=balloons, cover_art=cover, cover_sub=cover_sub,
             cover_say=cover_say, wrap_recap=recap, teaser=teaser, cast={k: [v[0], v[1]] for k, v in cast.items()}, lines=lines, quiz=quiz,
             rdg_q=rdg, dictate=dictate, produce=pr, rs=rsd(rs), sc=sc)
    X = dict(n=n, review=True, names=names, stage=stage, obra=obra, gancho=gancho, hot=hot, gap=gap, trap=trap, sticker=sticker,
             speakers={k: v[2] for k, v in cast.items()}, rule=rule, mission_ic=mission_ic)
    XT = dict(exp=exp, exp_scene=exp_scene, lab=lab, hunt=hunt)
    return dict(B=B, X=X, XT=XT, VB=verbs, MR=MR, CX=CX)


